<script setup>
import { computed, reactive, ref, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { toAwardDraft, toAwardPayload } from '../domain/award-write.mjs';
const props=defineProps({record:{type:Object,default:()=>({})},editing:Boolean,saving:Boolean,error:String});const emit=defineEmits(['cancel','save']);const draft=reactive({ ...toAwardDraft(props.record) });const localError=ref('');const title=computed(()=>props.editing?'Sửa giải thưởng':'Thêm giải thưởng');const showCost=computed(()=>!props.editing||Object.hasOwn(props.record,'cost'));const types=['gov','association','other'].map(value=>({value,label:value==='gov'?'Cơ quan nhà nước':value==='association'?'Hiệp hội':'Khác'}));const statuses=['','Đang mở','Đã đóng','Đã hoàn tất'].map(value=>({value,label:value||'Chọn trạng thái'}));watch(()=>props.record,record=>Object.assign(draft,toAwardDraft(record)),{deep:true});function submit(){try{localError.value='';emit('save',toAwardPayload(draft,{existingRecord:props.editing?props.record:null}));}catch(error){localError.value=error.message;}}
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><form class="mx-auto max-w-[880px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]" @submit.prevent="submit"><header class="flex items-start justify-between gap-4 border-b border-[var(--mds-border-light)] px-5 py-4"><div><h1 class="text-[20px] font-semibold">{{title}}</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Thông tin giải thưởng; máy chủ kiểm tra lại quyền khi lưu.</p></div><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton></header><div class="grid gap-4 p-5 sm:grid-cols-2"><label class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Tên giải thưởng *</span><MInput v-model="draft.name" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Đơn vị tổ chức</span><MInput v-model="draft.organizer" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Loại đơn vị</span><MSelect v-model="draft.organizer_type" :options="types" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Hạn nộp</span><MInput v-model="draft.submission_deadline" type="date" :disabled="saving"/></label><label v-if="showCost"><span class="mb-1 block text-[13px] font-medium">Chi phí tham gia (đ)</span><MInput v-model="draft.cost" type="number" min="0" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Phạm vi</span><MInput v-model="draft.scope" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Trạng thái</span><MSelect v-model="draft.status" :options="statuses" :disabled="saving"/></label><label class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Điều kiện</span><MTextarea v-model="draft.eligibility" :disabled="saving"/></label><label class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Tiêu chí</span><MTextarea v-model="draft.criteria" :disabled="saving"/></label><label class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Hồ sơ cần thiết</span><MTextarea v-model="draft.required_docs" :disabled="saving"/></label><label class="sm:col-span-2"><span class="mb-1 block text-[13px] font-medium">Ghi chú</span><MTextarea v-model="draft.note" :disabled="saving"/></label></div><p v-if="error||localError" role="alert" class="mx-5 mb-4 rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{error||localError}}</p><footer class="sticky bottom-0 flex justify-end gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-5 py-3"><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" :loading="saving" :disabled="saving" @click="submit">Lưu giải thưởng</MButton></footer></form></section></template>
